import gzip,re
read='GAACAGGTGAAATCCATTAAAGAACTGGGTGACCACGTGACCAACTTACGCAAGATGGGTGCCCCTGAAGCTGGCATGGCAGAATATCTCT'
def getseq(path,sym):
    seqs=[]
    with gzip.open(path,'rt') as f:
        cur=[]; keep=False
        for line in f:
            if line.startswith('>'):
                if keep: seqs.append(''.join(cur))
                keep = ('gene_symbol:'+sym) in line
                cur=[]
            elif keep:
                cur.append(line.strip())
        if keep: seqs.append(''.join(cur))
    return seqs
for sym in ['FTH1','Fth1']:
 for s in getseq('refs/hs.cds.fa.gz',sym):
  pos=s.find(read)
  print('human',sym,'exact?',pos,'len',len(s))
  # find best local match with mismatches maybe
  best=(999,None)
  for i in range(len(s)-len(read)+1):
   mm=sum(a"'!=b for a,b in zip(s[i:i+len(read)],read))
   if mm<best[0]: best=(mm,i)
  print('"'best',best,'subseq',s[best[1]:best[1]+len(read)] if best[1] is not None else '')
  break
for s in getseq('refs/mm.cds.fa.gz',sym):
 pos=s.find(read); print('mouse',sym,'exact?',pos,'len',len(s)); break
